BEGIN;
CREATE TABLE IF NOT EXISTS glowbb.participant_profiles(participant_id TEXT PRIMARY KEY REFERENCES glowbb.participants(id),revision INTEGER NOT NULL,details TEXT NOT NULL,updated TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES glowbb.users(id));
CREATE TABLE IF NOT EXISTS glowbb.profile_history(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES glowbb.participants(id),details TEXT NOT NULL,created TEXT NOT NULL,effective_date TEXT,source TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES glowbb.users(id));
CREATE TABLE IF NOT EXISTS glowbb.profile_observations(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES glowbb.participants(id),field TEXT NOT NULL,raw TEXT,recorded TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS glowbb.participant_feedback(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES glowbb.participants(id),date TEXT NOT NULL,details TEXT NOT NULL,created TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES glowbb.users(id));
CREATE TABLE IF NOT EXISTS glowbb.needs_actions(id TEXT PRIMARY KEY,kind TEXT NOT NULL,revision INTEGER NOT NULL,details TEXT NOT NULL,created TEXT NOT NULL,updated TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES glowbb.users(id));
CREATE TABLE IF NOT EXISTS glowbb.member_registry(participant_id TEXT NOT NULL REFERENCES glowbb.participants(id),snapshot TEXT NOT NULL,details TEXT NOT NULL,PRIMARY KEY(participant_id,snapshot));
CREATE INDEX IF NOT EXISTS feedback_participant ON glowbb.participant_feedback(participant_id,date);
CREATE INDEX IF NOT EXISTS profile_history_participant ON glowbb.profile_history(participant_id,created);
ALTER TABLE glowbb.participant_profiles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON glowbb.participant_profiles FROM PUBLIC,anon,authenticated;
ALTER TABLE glowbb.profile_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON glowbb.profile_history FROM PUBLIC,anon,authenticated;
ALTER TABLE glowbb.profile_observations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON glowbb.profile_observations FROM PUBLIC,anon,authenticated;
ALTER TABLE glowbb.participant_feedback ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON glowbb.participant_feedback FROM PUBLIC,anon,authenticated;
ALTER TABLE glowbb.needs_actions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON glowbb.needs_actions FROM PUBLIC,anon,authenticated;
ALTER TABLE glowbb.member_registry ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON glowbb.member_registry FROM PUBLIC,anon,authenticated;
INSERT INTO glowbb.schema_version VALUES(4) ON CONFLICT DO NOTHING;
COMMIT;
